package com.jadhavr.erp.audit.controller; import com.jadhavr.erp.audit.enums.*; import com.jadhavr.erp.audit.service.AuditLogService; import com.jadhavr.erp.common.api.ApiResponse; import org.springframework.format.annotation.DateTimeFormat; import org.springframework.web.bind.annotation.*; import java.time.LocalDate; @RestController @RequestMapping("/api/audit-logs") public class AuditLogController {private final AuditLogService service;public AuditLogController(AuditLogService s){service=s;}@GetMapping public ApiResponse<?> search(@RequestParam(required=false)String keyword,@RequestParam(required=false)Long collegeId,@RequestParam(required=false)AuditModule module,@RequestParam(required=false)AuditAction action,@RequestParam(required=false)Long actorUserId,@RequestParam(required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE)LocalDate dateFrom,@RequestParam(required=false)@DateTimeFormat(iso=DateTimeFormat.ISO.DATE)LocalDate dateTo,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="10")int size){return ApiResponse.success("Audit logs",service.search(keyword,collegeId,module,action,actorUserId,dateFrom,dateTo,page,size));}}
